<?php
namespace App\Filament\Admin\Resources\PaymentRequests\Pages;use App\Filament\Admin\Concerns\ServiceValidation;use App\Filament\Admin\Resources\PaymentRequests\PaymentRequestResource;use Filament\Actions\Action;use Filament\Resources\Pages\ViewRecord;final class ViewPaymentRequest extends ViewRecord{protected static string $resource=PaymentRequestResource::class;protected function getHeaderActions():array{return[Action::make('initiate')->label('Send payment prompt')->icon('heroicon-o-device-phone-mobile')->color('primary')->requiresConfirmation()->visible(fn()=>in_array($this->record->status,['CREATED','PENDING_CUSTOMER','FAILED'],true))->action(function(){if(ServiceValidation::run(fn()=>app(\App\Application\Payments\PaymentInitiationService::class)->initiate($this->record))===null)return;})];}}
